import{_ as t,c as s,o as r,j as n,Y as o,t as i}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"memusagestat | x-cmd man (man1) | generate graphic from memory profiling data","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | memusagestat - generate graphic from memory profiling data","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"memusagestat | x-cmd man (man1) | generate graphic from memory profiling data"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | memusagestat - generate graphic from memory profiling data"}]]},"headers":[],"params":{"isMan":true,"man":"memusagestat","category":"man1","desc":"generate graphic from memory profiling data"},"relativePath":"man1/memusagestat.md","filePath":"man1/[man].md"}'),m={name:"man1/memusagestat.md"},d={class:"visually-hidden"};function g(a,e,l,h,p,c){return r(),s("div",null,[n("h1",d,i(a.$params.man),1),e[0]||(e[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>memusagestat - generate graphic from memory profiling data</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">memusagestat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [option]... datafile [outfile]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>memusagestat</strong> creates a PNG file containing a graphical representation of the memory profiling data in the file <em>datafile</em>; that file is generated via the <em>-d</em> (or <em>--data</em>) option of <strong>memusage</strong>(1).</p><p>The red line in the graph shows the heap usage (allocated memory) and the green line shows the stack usage. The x-scale is either the number of memory-handling function calls or (if the <em>-t</em> option is specified) time.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>-o</strong> <em>file</em>* *, <strong>--output=</strong> **<em>file</em></dt><dd>Name of the output file.</dd><dt><strong>-s</strong> <em>string</em>* *, <strong>--string=</strong> **<em>string</em></dt><dd>Use <em>string</em> as the title inside the output graph.</dd><dt>**-t, <strong>--time</strong> **</dt><dd>Use time (rather than number of function calls) as the scale for the X axis.</dd><dt>**-T, <strong>--total</strong> **</dt><dd>Also draw a graph of total memory consumption.</dd><dt><strong>-x</strong> <em>size</em>* *, <strong>--x-size=</strong> **<em>size</em></dt><dd>Make the output graph <em>size</em> pixels wide.</dd><dt><strong>-y</strong> <em>size</em>* *, <strong>--y-size=</strong> **<em>size</em></dt><dd>Make the output graph <em>size</em> pixels high.</dd><dt>**-?, <strong>--help</strong> **</dt><dd>Print a help message and exit.</dd><dt><strong>--usage</strong></dt><dd>Print a short usage message and exit.</dd><dt>**-V, <strong>--version</strong> **</dt><dd>Print version information and exit.</dd></dl><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>To report bugs, see <a href="http://www.gnu.org/software/libc/bugs.html" target="_blank" rel="noreferrer"></a></p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>See <strong>memusage</strong>(1).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>memusage</strong>(1), <strong>mtrace</strong>(1)</p>',15))])}const b=t(m,[["render",g]]);export{f as __pageData,b as default};
